create table if not exists public.connections (id uuid primary key default gen_random_uuid(), requester_id uuid not null references public.profiles(id) on delete cascade, offer_owner_id uuid not null references public.profiles(id) on delete cascade, offer_id uuid not null references public.offers(id) on delete restrict, status text not null default 'pending' check(status in ('pending','accepted','rejected','cancelled')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(requester_id<>offer_owner_id));
alter table public.connections add column if not exists requester_id uuid; alter table public.connections add column if not exists offer_owner_id uuid; alter table public.connections add column if not exists offer_id uuid; alter table public.connections add column if not exists status text default 'pending'; alter table public.connections add column if not exists created_at timestamptz default now(); alter table public.connections add column if not exists updated_at timestamptz default now();
